import re

def evaluate(expr: str) -> float:
    # Tokenize input
    tokens = []
    i = 0
    n = len(expr)

    # Track whether the next '-' should be treated as unary negation
    # At the start of an expression, or right after an operator or '(', '-' is unary.
    can_be_unary = True

    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        elif c in '+*/':
            tokens.append(c)
            can_be_unary = True
            i += 1
        elif c == '-':
            if can_be_unary:
                tokens.append('neg')
            else:
                tokens.append('-')
            can_be_unary = True
            i += 1
        elif c == '(':
            tokens.append('(')
            can_be_unary = True
            i += 1
        elif c == ')':
            tokens.append(')')
            can_be_unary = False
            i += 1
        elif c.isdigit() or c == '.':
            match = re.match(r'^\d+(\.\d*)?|^\.\d+', expr[i:])
            if not match:
                raise ValueError(f"Malformed number starting at index {i}")
            num_str = match.group(0)
            tokens.append(float(num_str))
            i += len(num_str)
            can_be_unary = False
        else:
            raise ValueError(f"Unknown character: {c}")

    if not tokens:
        raise ValueError("Empty expression")

    # Shunting-yard algorithm to convert tokens to Reverse Polish Notation (RPN)
    precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '/': 2,
        'neg': 3
    }

    output_queue = []
    op_stack = []

    # Validate token sequence structure
    for idx, token in enumerate(tokens):
        if token in ('+', '-', '*', '/'):
            if idx == 0 or idx == len(tokens) - 1:
                raise ValueError("Binary operator at boundary")
            prev = tokens[idx - 1]
            if prev in ('+', '-', '*', '/', 'neg', '('):
                raise ValueError("Consecutive operators")
        elif token == 'neg':
            if idx == len(tokens) - 1:
                raise ValueError("Trailing unary minus")
            next_token = tokens[idx + 1]
            if next_token in ('+', '-', '*', '/'):
                raise ValueError("Unary minus followed by binary operator")

    for token in tokens:
        if isinstance(token, float):
            output_queue.append(token)
        elif token == 'neg':
            # Unary minus is right-associative with highest precedence
            while op_stack and op_stack[-1] != '(' and precedence[op_stack[-1]] > precedence['neg']:
                output_queue.append(op_stack.pop())
            op_stack.append(token)
        elif token in precedence:
            # Binary operators (+, -, *, /) are left-associative
            while (op_stack and op_stack[-1] != '(' and 
                   precedence[op_stack[-1]] >= precedence[token]):
                output_queue.append(op_stack.pop())
            op_stack.append(token)
        elif token == '(':
            op_stack.append(token)
        elif token == ')':
            while op_stack and op_stack[-1] != '(':
                output_queue.append(op_stack.pop())
            if not op_stack:
                raise ValueError("Unbalanced parentheses")
            op_stack.pop()

    while op_stack:
        top = op_stack.pop()
        if top == '(':
            raise ValueError("Unbalanced parentheses")
        output_queue.append(top)

    # Evaluate RPN
    eval_stack = []
    for item in output_queue:
        if isinstance(item, float):
            eval_stack.append(item)
        elif item == 'neg':
            if not eval_stack:
                raise ValueError("Malformed expression")
            val = eval_stack.pop()
            eval_stack.append(-val)
        else:
            if len(eval_stack) < 2:
                raise ValueError("Malformed expression")
            b = eval_stack.pop()
            a = eval_stack.pop()
            if item == '+':
                eval_stack.append(a + b)
            elif item == '-':
                eval_stack.append(a - b)
            elif item == '*':
                eval_stack.append(a * b)
            elif item == '/':
                if b == 0.0:
                    raise ZeroDivisionError("Division by zero")
                eval_stack.append(a / b)

    if len(eval_stack) != 1:
        raise ValueError("Malformed expression")

    return float(eval_stack[0])
